import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";

const PATCH_ID = "contratos-pagamento-layout-fabrica-v2";
const FILES = {
  "app/src/main/java/br/com/usinagemmaster/data/local/dao/ContractDao.kt": "",
  "app/src/main/java/br/com/usinagemmaster/data/repository/GameRepositoryImpl.kt": "",
  "app/src/main/java/br/com/usinagemmaster/domain/repository/GameRepository.kt": "",
  "app/src/main/java/br/com/usinagemmaster/feature/contracts/ContractsScreen.kt": "",
  "app/src/main/java/br/com/usinagemmaster/feature/contracts/ContractsViewModel.kt": "",
  "app/src/main/java/br/com/usinagemmaster/feature/machines/MachinesScreen.kt": ""
};
const HASHES = {
  "app/src/main/java/br/com/usinagemmaster/data/local/dao/ContractDao.kt": "999e2a401d7b1545d8303321ef5cd06b06a6a62aba7c1c55a6955b6c73673ad5",
  "app/src/main/java/br/com/usinagemmaster/data/repository/GameRepositoryImpl.kt": "84675b5cd724c8eab8d223bb2e9016b3abbf9f1e8ce99f162b40763199d1e952",
  "app/src/main/java/br/com/usinagemmaster/domain/repository/GameRepository.kt": "cb20b586bee6a7c527c7f26e63f0316735612d4854a0088167fc682ca6f36b70",
  "app/src/main/java/br/com/usinagemmaster/feature/contracts/ContractsScreen.kt": "46903e038bd321c16c8afc38bed721ca115262d2b1a325ce561b5627fd29cf38",
  "app/src/main/java/br/com/usinagemmaster/feature/contracts/ContractsViewModel.kt": "d86fd8ab3db10dea96dd1a933b7c770162d58c1e79da28b868d1fcded8bf8c23",
  "app/src/main/java/br/com/usinagemmaster/feature/machines/MachinesScreen.kt": "eca5efcf3c9341edbaf396a2a8dd4de1b30b4900d744a9d580aa21731c6332d2"
};
const args = new Set(process.argv.slice(2));
const root = process.cwd();
const required = ["settings.gradle.kts", "app"];
for (const item of required) { if (!fs.existsSync(path.join(root,item))) { console.error(`[ERRO] Execute este script na raiz do projeto. Não encontrei ${item}.`); process.exit(1); } }
const backupDir=path.join(root,".patch-backups",PATCH_ID);
const sha=b=>crypto.createHash("sha256").update(b).digest("hex");
if (args.has("--restore")) {
  if (!fs.existsSync(backupDir)) { console.error("[ERRO] Backup não encontrado: "+backupDir); process.exit(1); }
  for (const rel of Object.keys(FILES)) { const b=path.join(backupDir,rel); const t=path.join(root,rel); if (fs.existsSync(b)) { fs.mkdirSync(path.dirname(t),{recursive:true}); fs.copyFileSync(b,t); console.log("[RESTORE] "+rel); } }
  console.log("[OK] Restauração concluída."); process.exit(0);
}
for (const rel of Object.keys(FILES)) { if (!fs.existsSync(path.join(root,rel))) { console.error("[ERRO] Arquivo esperado não encontrado: "+rel); process.exit(1); } }
console.log("[OK] Projeto encontrado: "+root);
console.log("[INFO] Esta FIX corrige:");
console.log("  • pagamento de contratos concluídos");
console.log("  • recuperação de prêmio antigo não creditado");
console.log("  • Fábrica Viva inteira rolável; cabeçalho/bônus/copa deixam de ficar fixos");
if (args.has("--dry-run")) { console.log("[DRY-RUN] Nenhum arquivo foi alterado."); process.exit(0); }
for (const [rel,b64] of Object.entries(FILES)) {
  const target=path.join(root,rel), backup=path.join(backupDir,rel);
  fs.mkdirSync(path.dirname(backup),{recursive:true});
  if (!fs.existsSync(backup)) fs.copyFileSync(target,backup);
  const data=Buffer.from(b64,"base64"); fs.writeFileSync(target,data);
  if (sha(fs.readFileSync(target))!==HASHES[rel]) throw new Error("Falha de validação: "+rel);
  console.log("[OK] Atualizado: "+rel);
}
console.log("\n[SUCESSO] FIX aplicada.");
console.log("Abra Contratos: se o contrato antigo ficou CONCLUÍDO sem dinheiro, use ‘Não recebeu? Recuperar prêmio’. ");
console.log("Na Fábrica Viva, role a página normalmente: Chão de fábrica, bônus, +10 min, Copa e foco não ficam mais presos no topo.");
console.log("\nAgora rode: .\\gradlew.bat clean && .\\gradlew.bat assembleDebug");
console.log("Para desfazer: node aplicar-fix-contratos-layout-fabrica.mjs --restore");
